<script setup>
import { ref, watch, nextTick, onUnmounted, computed } from 'vue'
import { CalendarCheck, Users } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import * as echarts from 'echarts/core'
import { PieChart } from 'echarts/charts'
import { TooltipComponent, LegendComponent, TitleComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { useWorkspace } from '../stores/workspace'
import { api, today, shiftName, downloadCSV } from '../services/api'
import NurseAvatar from '../components/NurseAvatar.vue'
echarts.use([PieChart,TooltipComponent,LegendComponent,TitleComponent,CanvasRenderer])
const s=useWorkspace(), period=ref('week'), result=ref(null), loading=ref(false), detail=ref(null), opened=ref(false), chartNode=ref(null), query=ref('')
const visibleRows=computed(()=>(result.value?.rows||[]).filter(row=>!query.value||row.name.includes(query.value)))
let chart,observer,timer,latestRequest=0,selectedNurse=null
async function load(){
  const seq=++latestRequest;loading.value=true
  try{
    const value=await api('workload/?'+new URLSearchParams({...s.groupPayload(),period:period.value,date:today()}))
    if(seq!==latestRequest)return
    result.value=value
    if(opened.value){detail.value=[...value.rows,...(value.historical_rows||[])].find(r=>r.id===selectedNurse);if(detail.value)await draw();else opened.value=false}
  }catch(e){if(seq===latestRequest)ElMessage.error(e.message)}finally{if(seq===latestRequest)loading.value=false}
}
async function draw(){await nextTick();if(!chartNode.value||!detail.value)return;if(chart)chart.dispose();chart=echarts.init(chartNode.value);chart.setOption({color:['#218aff','#38cda0','#f3a13c','#a17be4'],tooltip:{trigger:'item',formatter:'{b}：{c}小时（{d}%）'},title:{text:detail.value.hours+'',subtext:'总工时 / 小时',left:'center',top:'38%',textStyle:{fontSize:30,color:'#173c6a'},subtextStyle:{fontSize:11}},legend:{bottom:0},series:[{type:'pie',radius:['56%','76%'],center:['50%','45%'],label:{show:false},data:Object.entries(detail.value.hour_distribution).map(([name,value])=>({name,value}))}]});observer?.disconnect();observer=new ResizeObserver(()=>chart?.resize());observer.observe(chartNode.value)}
function show(row){selectedNurse=row.id;detail.value=row;opened.value=true}
function exportReport(){downloadCSV('护士工作量-'+period.value+'.csv',[['统计来源：正式发布记录，非考勤'],['护士','A班','白班','N班','总班次','管床患者人次','状态'],...[...result.value.rows,...(result.value.historical_rows||[])].map(r=>[r.name,r.A,r.DAY,r.N,r.total_shifts,r.patients,r.historical?'已删除人员历史':'当前人员'])])}
watch([period,()=>s.group],(value,previous)=>{result.value=null;detail.value=null;if(previous&&value[1]!==previous[1]){opened.value=false;selectedNurse=null}load()},{immediate:true})
timer=setInterval(()=>{if(!document.hidden)load()},15000)
onUnmounted(()=>{latestRequest++;clearInterval(timer);observer?.disconnect();chart?.dispose()})
</script>
<template><div class="page-heading"><div><h1>工作量统计</h1><p>按最终发布的班次与床位责任记录汇总</p></div><div class="actions"><el-radio-group v-model="period"><el-radio-button value="week">本周</el-radio-button><el-radio-button value="month">本月</el-radio-button></el-radio-group><span class="muted small">{{result?.start}} 至 {{result?.end}}</span><el-button :disabled="!result" @click="exportReport">导出报表</el-button></div></div><div v-loading="loading"><template v-if="result"><div class="kpis two"><div class="kpi"><span class="symbol"><CalendarCheck/></span><div><label>总上班人次</label><strong>{{result.total_shifts}}</strong><small>次</small></div></div><div class="kpi"><span class="symbol"><Users/></span><div><label>累计管床患者人次</label><strong>{{result.patients}}</strong><small>人次</small></div></div></div><section class="card"><div class="card-title"><h2>护士工作量统计</h2><el-input v-model="query" placeholder="搜索护士姓名" clearable style="width:200px"/></div><el-table :data="visibleRows"><el-table-column label="护士" min-width="190"><template #default="{row}"><el-button link type="primary" @click="show(row)"><NurseAvatar :nurse="s.data.nurses.find(n=>n.id===row.id)||row"/><b style="margin-left:12px">{{row.name}}</b><el-tag size="small">{{row.level}}</el-tag></el-button><p class="small muted" style="margin:7px 0 0">{{row.skills.join('、')||'—'}}</p></template></el-table-column><el-table-column prop="A" label="A班（次）" sortable/><el-table-column prop="DAY" label="白班（次）" sortable/><el-table-column prop="N" label="N班（次）" sortable/><el-table-column prop="total_shifts" label="总班次" sortable/><el-table-column prop="patients" label="累计管床患者人次" min-width="155" sortable/><el-table-column label="操作" width="120"><template #default="{row}"><el-button plain size="small" @click="show(row)">查看详情</el-button></template></el-table-column></el-table><el-collapse v-if="result.historical_rows?.length" class="section-gap"><el-collapse-item :title="'已删除人员历史工作量（'+result.historical_rows.length+'人）'" name="history"><p class="muted small">仅保留本期已发布历史事实，不再计入当前人员列表；汇总指标包括这些记录。</p><el-table :data="result.historical_rows" size="small"><el-table-column prop="name" label="原姓名"/><el-table-column prop="employee_id" label="原工号"/><el-table-column prop="A" label="A班"/><el-table-column prop="DAY" label="白班"/><el-table-column prop="N" label="N班"/><el-table-column prop="total_shifts" label="总班次"/><el-table-column prop="patients" label="管床人次"/><el-table-column label="详情"><template #default="{row}"><el-button link type="primary" @click="show(row)">查看详情</el-button></template></el-table-column></el-table></el-collapse-item></el-collapse><el-alert :title="result.source" type="info" :closable="false" class="section-gap"/></section></template></div>
<el-drawer v-model="opened" title="护士工作量详情" size="560px" @opened="draw" @closed="chart?.dispose();chart=null;observer?.disconnect()"><template v-if="detail"><div class="card-title"><h2><NurseAvatar :nurse="s.data.nurses.find(n=>n.id===detail.id)||detail"/> {{detail.name}} <el-tag>{{detail.level}}</el-tag></h2><el-radio-group v-model="period" size="small"><el-radio-button value="week">本周</el-radio-button><el-radio-button value="month">本月</el-radio-button></el-radio-group></div><p class="muted small">{{detail.skills.join('、')}}</p><h3>班次工时分布</h3><div ref="chartNode" class="donut"></div><div class="chart-legend"><span v-for="(hours,name) in detail.hour_distribution" :key="name">{{name}} <b>{{hours}}小时</b>（{{detail.hours?(hours/detail.hours*100).toFixed(1):0}}%）</span></div><div class="kpis two section-gap"><div class="kpi"><div><label>上班次数</label><strong>{{detail.total_shifts}}</strong><small>次</small></div></div><div class="kpi"><div><label>管床患者人次</label><strong>{{detail.patients}}</strong><small>人次</small></div></div></div><h3>每日明细</h3><el-table :data="detail.daily" size="small"><el-table-column prop="date" label="日期" width="100"/><el-table-column label="最终班次" width="80"><template #default="{row}"><span :class="['shift-badge','shift-'+row.shift]">{{shiftName(row.shift)}}</span></template></el-table-column><el-table-column label="分管床位"><template #default="{row}">{{row.beds.join('、')||'—'}}</template></el-table-column><el-table-column prop="patients" label="患者人次" width="80"/><el-table-column prop="hours" label="工时(h)" width="75"/></el-table><el-alert title="工时按发布时有效班次设置计算，N班归开始日期；休和夜下休为0小时。未连接实际考勤。" type="info" :closable="false" class="section-gap"/></template></el-drawer></template>
